oxy_webhelp_navlinks = {"aws_manage_cld_acc-d39307e17633":{"topics":[{"title":"Viewing the AWS accounts page","shortdesc":"<p class=\"shortdesc\">Access the AWS accounts page to view information about the cloud accounts created on         <span class=\"ph\">RSC<\/span>.<\/p>","href":"saas\/viewing_the_aws_accounts_page.html","attributes":{"data-id":"viewing_the_aws_accounts_page"},"menu":{"hasChildren":false},"tocID":"viewing_the_aws_accounts_page-d39307e17647","next":"viewing_the_aws_accounts_page-d39307e17647"},{"title":"Updating an individual AWS account permissions by template","shortdesc":"<p class=\"shortdesc\">Update permissions for an individual AWS cloud account to ensure that the required         permissions for the new features are included in <span class=\"ph\">RSC<\/span>. You can use the AWS         CloudFormation template to update the permissions. You can also remove permissions that are         no longer needed.<\/p>","href":"saas\/aws_updating_indv_acc_perms_template.html","attributes":{"data-id":"aws_updating_indv_acc_perms_template"},"menu":{"hasChildren":false},"tocID":"aws_updating_indv_acc_perms_template-d39307e17675","topics":[]},{"title":"Updating permissions for AWS Organization accounts","shortdesc":"<p class=\"shortdesc\">Update permissions for all the AWS cloud accounts that are added using an AWS         Organization to ensure that the required permissions for the new features are included in             <span class=\"ph\">RSC<\/span>. You can use the AWS CloudFormation template to update the         permissions. You can also remove the permissions that are no longer needed.<\/p>","href":"saas\/aws_updating_perms_org_acc.html","attributes":{"data-id":"aws_updating_perms_org_acc"},"menu":{"hasChildren":false},"tocID":"aws_updating_perms_org_acc-d39307e17689","topics":[]},{"title":"Updating AWS account permissions manually","shortdesc":"<p class=\"shortdesc\">Update permissions for an AWS cloud account to ensure that the required permissions         for the new features are included in <span class=\"ph\">RSC<\/span>. You can update the permissions         manually. You can also remove unneeded permissions.<\/p>","href":"saas\/updating_aws_acnt_perms_manual.html","attributes":{"data-id":"updating_aws_acnt_perms_manual"},"menu":{"hasChildren":false},"tocID":"updating_aws_acnt_perms_manual-d39307e17703","topics":[]},{"title":"Upgrading an AWS cloud account","shortdesc":"<p class=\"shortdesc\">Upgrade an AWS cloud account in the \"Update permissions\" state to retrieve the         current set of permissions.<\/p>","href":"saas\/upgrading_an_aws_account.html","attributes":{"data-id":"upgrading_an_aws_account"},"menu":{"hasChildren":false},"tocID":"upgrading_an_aws_account-d39307e17717","topics":[]},{"title":"Edit an AWS account","shortdesc":"<p class=\"shortdesc\">You can edit an existing AWS account in <span class=\"ph\">RSC<\/span> to change the data         protection preferences for your AWS account.<\/p>","href":"saas\/edit_aws_account.html","attributes":{"data-id":"edit_aws_account"},"menu":{"hasChildren":false},"tocID":"edit_aws_account-d39307e17728","topics":[]},{"title":"Migrating existing AWS accounts to AWS Organization","shortdesc":"<p class=\"shortdesc\">Migrate existing AWS accounts to an AWS Organization. When you choose to migrate an         AWS account to an AWS Organization, <span class=\"ph\">RSC<\/span> selects all the AWS accounts         eligible for migration instead of providing an option to select which accounts to         migrate.<\/p>","href":"saas\/aws_migrating_existing_acc_org.html","attributes":{"data-id":"aws_migrating_existing_acc_org"},"menu":{"hasChildren":false},"tocID":"aws_migrating_existing_acc_org-d39307e17742","topics":[]},{"title":"Delete AWS cloud accounts","shortdesc":"<p class=\"shortdesc\">You can delete an AWS cloud account from <span class=\"ph\">RSC<\/span> when it is no longer in         use.<\/p>","href":"saas\/aws_cloud_account_deletion.html","attributes":{"data-id":"aws_cloud_account_deletion"},"menu":{"hasChildren":false},"tocID":"aws_cloud_account_deletion-d39307e17756","next":"aws_cloud_account_deletion-d39307e17756"},{"title":"Disabling and deleting AWS cloud discovery","shortdesc":"<p class=\"shortdesc\">Disable and delete cloud discovery when you want to remove an AWS account integration         with <span class=\"ph\">RSC<\/span> or stop metadata collection.<\/p>","href":"saas\/aws_disabling_cloud_discovery.html","attributes":{"data-id":"aws_disabling_cloud_discovery"},"menu":{"hasChildren":false},"tocID":"aws_disabling_cloud_discovery-d39307e17795","topics":[]},{"title":"Deleting permissions for an Amazon RDS cloud account","shortdesc":"<p class=\"shortdesc\">Delete permissions for an Amazon RDS account project and delete the <span class=\"ph\">RSC<\/span> cloud         account.<\/p>","href":"saas\/aws_rds_deleting_cloud_account.html","attributes":{"data-id":"aws_rds_deleting_cloud_account"},"menu":{"hasChildren":false},"tocID":"aws_rds_deleting_cloud_account-d39307e17809","topics":[]},{"title":"Cloud workload dashboard for AWS","shortdesc":"<p class=\"shortdesc\">The cloud workload dashboard for AWS provides a high-level view of the objects within         your AWS accounts, classified by sensitivity, region, and object type.<\/p>","href":"saas\/cloud_workload_dashboard_aws.html","attributes":{"data-id":"cloud_workload_dashboard_aws"},"menu":{"hasChildren":false},"tocID":"cloud_workload_dashboard_aws-d39307e17824","topics":[]},{"title":"Manage an AWS role chaining account","shortdesc":"<p class=\"shortdesc\">You can manage an existing AWS role chaining account in <span class=\"ph\">RSC<\/span> by         downloading its CloudFormation template, revoking or restoring access, or removing the         account.<\/p>","href":"saas\/aws_manage_role_chaining_acc.html","attributes":{"data-id":"aws_manage_role_chaining_acc"},"menu":{"hasChildren":false},"tocID":"aws_manage_role_chaining_acc-d39307e17835","next":"aws_manage_role_chaining_acc-d39307e17835"},{"title":"Disabling data scanning for AWS accounts","shortdesc":"<p class=\"shortdesc\">Disable data scanning for an AWS account to stop the collection of data sensitivity         insights.<\/p>","href":"saas\/aws_disabling_data_scanning.html","attributes":{"data-id":"aws_disabling_data_scanning"},"menu":{"hasChildren":false},"tocID":"aws_disabling_data_scanning-d39307e17891","topics":[]},{"title":"AWS permission validation","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides the permission validation feature to run on-demand         checks for the AWS accounts added to <span class=\"ph\">RSC<\/span>, proactively identifying missing         permissions essential for protecting the AWS workloads.<\/p>","href":"saas\/aws_permission_validation.html","attributes":{"data-id":"aws_permission_validation"},"menu":{"hasChildren":false},"tocID":"aws_permission_validation-d39307e17902","next":"aws_permission_validation-d39307e17902"},{"title":"Troubleshooting RSC-managed AWS protection","shortdesc":"<p class=\"shortdesc\">Resolve common problems when you onboard or protect AWS accounts with the         RSC-managed model.<\/p>","href":"saas\/aws_hosted_troubleshooting.html","attributes":{"data-id":"aws_hosted_troubleshooting"},"menu":{"hasChildren":false},"tocID":"aws_hosted_troubleshooting-d39307e17929","topics":[]}]}};